/**
 * ConversationList Component
 *
 * List of all conversations
 * Phase 6: User Story 4 - Real-Time Message Reception
 */

import React, { useState, useMemo, useRef, useEffect, useCallback } from 'react';
import { ListGroup, Spinner } from 'react-bootstrap';
import { useVirtualizer } from '@tanstack/react-virtual';
import ConversationListItem from './ConversationListItem';
import ChatListHeader from './ChatListHeader';
import AdvancedFilters from './AdvancedFilters';

const ConversationList = ({
  conversations = [],
  activeConversationId,
  onSelect,
  onSearch,
  isLoading = false,
  availableLines = [],
  showLineSelector = false,
  isAdmin = false,
  onLoadMore,
  hasMore = false
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [readFilter, setReadFilter] = useState('all'); // 'all' | 'unread'
  const [selectedLineId, setSelectedLineId] = useState(null);
  const [showAdvancedFilters, setShowAdvancedFilters] = useState(false);
  const [advancedFilters, setAdvancedFilters] = useState({
    usuarios: 'todos',
    lineaNegocio: 'todos',
    estado: 'todos',
    ordenarPor: 'todas',
    fechaCreacion: null
  });

  const parentRef = useRef(null);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const isLoadingRef = useRef(false); // Track loading state to prevent multiple calls
  const [isSearchingBackend, setIsSearchingBackend] = useState(false);

  // Handle backend search when Enter is pressed
  const handleSearchSubmit = (term) => {
    if (onSearch && term.trim()) {
      setIsSearchingBackend(true);
      onSearch(term);
      // Reset flag after a delay
      setTimeout(() => setIsSearchingBackend(false), 1000);
    }
  };

  // Filter conversations in memory (fast, for loaded conversations)
  const filteredConversations = useMemo(() => {
    // Ensure conversations is always an array
    if (!Array.isArray(conversations)) {
      console.warn('Conversations is not an array:', conversations);
      return [];
    }

    let filtered = [...conversations];

    // Filter by search term (in-memory)
    if (searchTerm.trim()) {
      const search = searchTerm.toLowerCase();
      filtered = filtered.filter((conv) => {
        const name = conv.lead_name?.toLowerCase() || '';
        const phone = conv.phone_number?.toLowerCase() || '';
        const lastMessage = conv.last_message?.toLowerCase() || '';
        return name.includes(search) || phone.includes(search) || lastMessage.includes(search);
      });
    }

    // Filter by read status
    if (readFilter === 'unread') {
      filtered = filtered.filter((conv) => conv.unread_count > 0);
    }

    // Filter by selected line
    if (selectedLineId !== null) {
      filtered = filtered.filter((conv) => conv.line_id === selectedLineId);
    }

    // Apply advanced filters
    // Filter by usuarios (lead_id)
    if (advancedFilters.usuarios !== 'todos') {
      const leadId = parseInt(advancedFilters.usuarios);
      filtered = filtered.filter((conv) => conv.lead_id === leadId);
    }

    // Filter by lineaNegocio (phone line)
    if (advancedFilters.lineaNegocio !== 'todos') {
      const lineId = parseInt(advancedFilters.lineaNegocio);
      filtered = filtered.filter((conv) => conv.line_id === lineId);
    }

    // Filter by estado (message status)
    if (advancedFilters.estado !== 'todos') {
      filtered = filtered.filter((conv) => {
        // Only apply filter if conversation has status field
        if (conv.last_message_status) {
          return conv.last_message_status === advancedFilters.estado;
        }
        // If no status field, don't filter out
        return true;
      });
    }

    // Filter by date range
    if (advancedFilters.fechaCreacion) {
      const { start, end } = advancedFilters.fechaCreacion;
      if (start && end) {
        filtered = filtered.filter((conv) => {
          const dateToCheck = conv.last_message_at || conv.created_at;
          if (!dateToCheck) return true; // Don't filter out if no date

          const convDate = new Date(dateToCheck);
          // Skip if date is invalid
          if (isNaN(convDate.getTime())) return true;

          const startDate = new Date(start);
          const endDate = new Date(end);
          endDate.setHours(23, 59, 59, 999); // Include the entire end date
          return convDate >= startDate && convDate <= endDate;
        });
      }
    }

    // Sort conversations based on ordenarPor
    if (advancedFilters.ordenarPor !== 'todas') {
      filtered = [...filtered].sort((a, b) => {
        switch (advancedFilters.ordenarPor) {
          case 'mas_recientes':
            return new Date(b.last_message_at || b.created_at) - new Date(a.last_message_at || a.created_at);
          case 'mas_antiguos':
            return new Date(a.last_message_at || a.created_at) - new Date(b.last_message_at || b.created_at);
          default:
            return 0;
        }
      });
    }

    return filtered;
  }, [conversations, searchTerm, readFilter, selectedLineId, advancedFilters]);

  const handleSearchChange = (value) => {
    setSearchTerm(value);
    onSearch?.(value);
  };

  const handleReadFilterChange = (filter) => {
    setReadFilter(filter);
  };

  const handleLineChange = (lineId) => {
    setSelectedLineId(lineId);
  };

  const handleOpenFilters = () => {
    setShowAdvancedFilters(true);
  };

  const handleApplyFilters = (filters) => {
    setAdvancedFilters(filters);
  };

  // Virtualizer setup with dynamic measurement
  const virtualizer = useVirtualizer({
    count: filteredConversations.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 72, // Initial estimate, will be measured dynamically
    overscan: 5, // Render 5 extra items above and below viewport for smooth scrolling
  });

  // Handle scroll to load more conversations
  useEffect(() => {
    if (!parentRef.current || !hasMore || !onLoadMore) {
      return;
    }

    const container = parentRef.current;

    const handleScroll = () => {
      // Prevent multiple simultaneous loads
      if (isLoadingRef.current) {
        return;
      }

      const { scrollTop, scrollHeight, clientHeight } = container;
      const threshold = 200;

      if (scrollHeight - scrollTop - clientHeight < threshold) {
        isLoadingRef.current = true;
        setIsLoadingMore(true);

        onLoadMore()
          .finally(() => {
            isLoadingRef.current = false;
            setIsLoadingMore(false);
          });
      }
    };

    container.addEventListener('scroll', handleScroll);
    return () => {
      container.removeEventListener('scroll', handleScroll);
    };
  }, [hasMore, onLoadMore]);


  return (
    <div className="d-flex flex-column h-100">
      {/* Chat List Header */}
      <div className="flex-shrink-0">
        <ChatListHeader
          searchTerm={searchTerm}
          onSearchChange={handleSearchChange}
          onSearchSubmit={handleSearchSubmit}
          readFilter={readFilter}
          onReadFilterChange={handleReadFilterChange}
          selectedLineId={selectedLineId}
          availableLines={availableLines}
          onLineChange={handleLineChange}
          showLineSelector={showLineSelector}
          isAdmin={isAdmin}
          onOpenFilters={handleOpenFilters}
        />
      </div>

      {/* Conversations list */}
      <div
        ref={parentRef}
        className="flex-grow-1 overflow-auto"
        style={{ minHeight: 0 }}
      >
        {isLoading && conversations.length === 0 ? (
          <div className="text-center py-5">
            <Spinner animation="border" variant="primary" />
            <p className="text-muted mt-2">Cargando conversaciones...</p>
          </div>
        ) : filteredConversations.length === 0 ? (
          <div className="text-center py-5 px-3">
            <p className="text-muted">No se encontraron conversaciones</p>
            <small>
              {searchTerm || readFilter === 'unread' || selectedLineId
                ? 'Intenta ajustar tus filtros'
                : 'Las conversaciones aparecerán aquí cuando los clientes envíen mensajes a tus líneas de WhatsApp'}
            </small>
          </div>
        ) : (
          <>
            <ListGroup variant="flush">
              <div
                style={{
                  height: `${virtualizer.getTotalSize()}px`,
                  width: '100%',
                  position: 'relative',
                }}
              >
                {virtualizer.getVirtualItems().map((virtualItem) => {
                  const conv = filteredConversations[virtualItem.index];
                  // IMPORTANT: Include conversation_assignment_id for unique identification
                  // This allows multiple conversations with the same phone number (different users/campaigns)
                  const convId = conv.conversation_assignment_id
                    ? `${conv.line_id}:${conv.phone_number}:${conv.conversation_assignment_id}`
                    : `${conv.line_id}:${conv.phone_number}`;

                  return (
                    <div
                      key={convId}
                      data-index={virtualItem.index}
                      ref={virtualizer.measureElement}
                      style={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        width: '100%',
                        transform: `translateY(${virtualItem.start}px)`,
                      }}
                    >
                      <ConversationListItem
                        conversation={conv}
                        isActive={convId === activeConversationId}
                        onClick={() => onSelect(conv)}
                      />
                    </div>
                  );
                })}
              </div>
            </ListGroup>

            {/* Loading more indicator */}
            {isLoadingMore && (
              <div className="text-center py-3">
                <Spinner animation="border" variant="primary" size="sm" />
                <small className="text-muted ms-2">Cargando más conversaciones...</small>
              </div>
            )}

            {/* End of list indicator */}
            {!hasMore && conversations.length > 0 && (
              <div className="text-center py-3">
                <small className="text-muted">No hay más conversaciones</small>
              </div>
            )}
          </>
        )}
      </div>

      {/* Advanced Filters Modal */}
      <AdvancedFilters
        show={showAdvancedFilters}
        onHide={() => setShowAdvancedFilters(false)}
        onApply={handleApplyFilters}
        initialFilters={advancedFilters}
        availableLines={availableLines}
      />
    </div>
  );
};

export default ConversationList;

